javascript:(function(){'use strict';var KU='karrotTracker.url',KT='karrotTracker.token';function $(i){return document.getElementById(i)}function e(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}function x(){var t=(document.body&&document.body.innerText)||'',d={keyword:'',name:'',seller:'',rating:'',reviews:'',likes:'',optionsText:'',url:location.href};var og=document.querySelector('meta[property="og:title"]');if(og&&og.content)d.name=og.content.replace(/\s*[|\-–·•].*$/,'').trim();if(!d.name){var h1=document.querySelector('h1');if(h1)d.name=h1.innerText.trim()}if(!d.name)d.name=document.title.replace(/\s*[|\-–·•].*$/,'').trim();var m=t.match(/별점\s*([0-9]\.[0-9])/)||t.match(/(?:★|⭐)\s*([0-9]\.[0-9])/)||t.match(/([0-9]\.[0-9])\s*점/);if(m)d.rating=parseFloat(m[1]);m=t.match(/(?:후기|리뷰)\s*[\(\s]?\s*([\d,]+)/);if(m)d.reviews=parseInt(m[1].replace(/,/g,''),10);m=t.match(/(?:찜|관심)\s*[\(\s]?\s*([\d,]+)/);if(m)d.likes=parseInt(m[1].replace(/,/g,''),10);m=t.match(/(?:판매자|스토어|상점)\s*[:|\n]\s*([^\n]+)/);if(m)d.seller=m[1].trim().slice(0,40);if(d.name){var tk=d.name.split(/\s+/).filter(function(s){return s.length>=2})[0];if(tk)d.keyword=tk}var sel=(window.getSelection&&window.getSelection().toString().trim())||'';if(sel)d.optionsText=sel;else{var L=t.split(/\n/).map(function(s){return s.trim()}).filter(Boolean).filter(function(l){return/(\d+(?:\.\d+)?\s*(?:kg|킬로|키로|박스|상자|개|알|입|구|마리|통|팩|세트))/i.test(l)&&/[\d,]+\s*원/.test(l)}).slice(0,12);d.optionsText=L.join('\n')}return d}function M(d){var o=$('karrot-tracker-modal');if(o)o.remove();var m=document.createElement('div');m.id='karrot-tracker-modal';m.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:2147483647;display:flex;align-items:center;justify-content:center;font-family:-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo","Malgun Gothic",sans-serif;';function L(t){return'<div style="font-size:12px;color:#555;margin:8px 0 4px;font-weight:600;">'+t+'</div>'}function I(id,v){return'<input id="'+id+'" value="'+e(v)+'" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;box-sizing:border-box;font-size:14px;">'}function C(t,id,v){return'<div style="flex:1;">'+L(t)+I(id,v)+'</div>'}m.innerHTML='<div style="background:#fff;padding:20px 22px;border-radius:14px;max-width:520px;width:92%;max-height:88vh;overflow:auto;box-shadow:0 16px 40px rgba(0,0,0,.25);color:#222;"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;"><div style="font-size:17px;font-weight:700;">📊 당근 시세 추적기</div><button id="kt-x" style="border:none;background:transparent;font-size:22px;cursor:pointer;color:#999;">×</button></div><div style="font-size:12px;color:#666;margin-bottom:14px;line-height:1.45;">자동 추출 값을 확인/수정 후 <b>전송</b>. <b>옵션</b>은 한 줄=한 옵션 (예: <code>10개 14,820원</code>, <code>4.5kg 30000</code>).</div>'+L('검색어 (분류 키워드)')+I('kt-keyword',d.keyword)+L('상품명')+I('kt-name',d.name)+L('판매자')+I('kt-seller',d.seller)+'<div style="display:flex;gap:8px;">'+C('평점','kt-rating',d.rating)+C('후기수','kt-reviews',d.reviews)+C('찜수','kt-likes',d.likes)+'</div>'+L('옵션 (한 줄=한 옵션)')+'<textarea id="kt-options" rows="6" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;box-sizing:border-box;font:13px/1.4 ui-monospace,Menlo,Consolas,monospace;">'+e(d.optionsText)+'</textarea><div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;align-items:center;"><div id="kt-status" style="flex:1;font-size:12px;color:#666;"></div><button id="kt-settings" style="padding:8px 12px;border:1px solid #ddd;background:#fafafa;border-radius:8px;cursor:pointer;font-size:12px;">설정</button><button id="kt-cancel" style="padding:8px 14px;border:1px solid #ddd;background:#fff;border-radius:8px;cursor:pointer;">취소</button><button id="kt-send" style="padding:8px 18px;border:none;background:#FF6F0F;color:#fff;border-radius:8px;cursor:pointer;font-weight:700;">전송 →</button></div></div>';document.body.appendChild(m);$('kt-x').onclick=$('kt-cancel').onclick=function(){m.remove()};$('kt-settings').onclick=function(){localStorage.removeItem(KU);localStorage.removeItem(KT);m.remove();alert('설정 초기화됨. 북마클릿을 다시 눌러주세요.')};$('kt-send').onclick=function(){var u=localStorage.getItem(KU),tk=localStorage.getItem(KT),s=$('kt-status'),p={token:tk,keyword:$('kt-keyword').value.trim(),name:$('kt-name').value.trim(),seller:$('kt-seller').value.trim(),rating:parseFloat($('kt-rating').value)||'',reviews:parseInt($('kt-reviews').value,10)||'',likes:parseInt($('kt-likes').value,10)||'',optionsText:$('kt-options').value};if(!p.keyword||!p.name){s.textContent='⚠️ 검색어/상품명 필수';s.style.color='#d33';return}if(!p.optionsText.trim()){s.textContent='⚠️ 옵션 1줄 이상 필요';s.style.color='#d33';return}s.textContent='전송 중…';s.style.color='#666';fetch(u,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(p)}).then(function(){s.innerHTML='✓ 전송됨 — 시트에서 확인하세요.';s.style.color='#080';setTimeout(function(){m.remove()},1200)}).catch(function(er){s.textContent='✗ 전송 실패: '+(er&&er.message||er);s.style.color='#d33'})}}var u=localStorage.getItem(KU),t=localStorage.getItem(KT);if(!u){u=prompt('Apps Script Web App URL을 붙여넣으세요\n(시트 메뉴 → 🔐 Web App URL/토큰 보기)','');if(!u)return;u=u.trim();localStorage.setItem(KU,u)}if(!t){t=prompt('토큰을 붙여넣으세요','');if(!t)return;t=t.trim();localStorage.setItem(KT,t)}M(x())})();
